import{_ as a,o as s,c as t,a6 as n}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"请求行","description":"method、request-target 的四种形式、HTTP-version——请求起始行逐字段解析。","frontmatter":{"title":"请求行","description":"method、request-target 的四种形式、HTTP-version——请求起始行逐字段解析。","source":"https://daiw.org/manual/http11/request-line"},"headers":[],"relativePath":"manual/computer-programming/http11/request-line.md","filePath":"manual/computer-programming/http11/request-line.md"}'),r={name:"manual/computer-programming/http11/request-line.md"};function o(i,e,l,p,d,u){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="请求行" tabindex="-1">请求行 <a class="header-anchor" href="#请求行" aria-label="Permalink to &quot;请求行&quot;">​</a></h1><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request-line = method SP request-target SP HTTP-version</span></span>
<span class="line"><span>method       = token</span></span>
<span class="line"><span>HTTP-version = &quot;HTTP/&quot; DIGIT &quot;.&quot; DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>三个字段，两个 SP 分隔，<strong>分隔符必须恰好是一个空格</strong>（不是 OWS）。接收方遇到多个空格时不得「宽容地」合并——这同样是走私向量。</p><h2 id="method" tabindex="-1">method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;method&quot;">​</a></h2><p>大小写<strong>敏感</strong>，按惯例全大写。<code>get</code> 与 <code>GET</code> 是不同的方法名，服务端应对未知方法返回 <strong>501 (Not Implemented)</strong>，对已知但目标资源不支持的方法返回 <strong>405 (Method Not Allowed)</strong> 并带 <code>Allow</code> 字段。</p><p>详见<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>。</p><h2 id="request-target" tabindex="-1">request-target <a class="header-anchor" href="#request-target" aria-label="Permalink to &quot;request-target&quot;">​</a></h2><p>四种形式，用哪种取决于方法与是否经代理：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>request-target = origin-form / absolute-form / authority-form / asterisk-form</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="origin-form" tabindex="-1">origin-form <a class="header-anchor" href="#origin-form" aria-label="Permalink to &quot;origin-form&quot;">​</a></h3><p>最常见形式。直连服务器时的绝大多数请求用它：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>origin-form = absolute-path [ &quot;?&quot; query ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /where?q=now HTTP/1.1</span></span>
<span class="line"><span>Host: www.example.org</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>要点：</p><ul><li><strong>绝对路径不得为空</strong>——若 URI 无路径分量，必须发 <code>/</code>。</li><li><strong>不含</strong>方案与 authority；目标主机由 <code>Host</code> 字段给出。</li><li>fragment（<code>#...</code>）<strong>永不</strong>出现在 request-target 中，由客户端本地处理。</li></ul><h3 id="absolute-form" tabindex="-1">absolute-form <a class="header-anchor" href="#absolute-form" aria-label="Permalink to &quot;absolute-form&quot;">​</a></h3><p>发往<strong>正向代理</strong>时必须用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>absolute-form = absolute-URI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET http://www.example.org/pub/WWW/ HTTP/1.1</span></span>
<span class="line"><span>Host: www.example.org</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>要点：</p><ul><li>客户端向代理发请求时 <strong>MUST</strong> 用此形式。</li><li>服务端 <strong>MUST</strong> 接受此形式（即使自己不是代理），以兼容将来经代理转发的情况。</li><li>同时仍需发 <code>Host</code>，且当两者冲突时，<strong>接收方 MUST 忽略 <code>Host</code> 而以 absolute-form 中的 authority 为准</strong>。</li></ul><h3 id="authority-form" tabindex="-1">authority-form <a class="header-anchor" href="#authority-form" aria-label="Permalink to &quot;authority-form&quot;">​</a></h3><p>仅用于 <strong>CONNECT</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authority-form = uri-host &quot;:&quot; port</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONNECT server.example.com:80 HTTP/1.1</span></span>
<span class="line"><span>Host: server.example.com:80</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>主机与端口都<strong>不可省略</strong>。</p><h3 id="asterisk-form" tabindex="-1">asterisk-form <a class="header-anchor" href="#asterisk-form" aria-label="Permalink to &quot;asterisk-form&quot;">​</a></h3><p>仅用于针对服务器整体（而非某资源）的 <strong>OPTIONS</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OPTIONS * HTTP/1.1</span></span>
<span class="line"><span>Host: www.example.org</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="http-version" tabindex="-1">HTTP-version <a class="header-anchor" href="#http-version" aria-label="Permalink to &quot;HTTP-version&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP-version = &quot;HTTP/&quot; DIGIT &quot;.&quot; DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>严格两位数字、一个点，<strong>不允许</strong>多位数字或省略次版本号（<code>HTTP/1</code> 非法）。</p><p>处理规则：</p><ul><li>服务端收到 major 版本不支持的请求 → <strong>505 (HTTP Version Not Supported)</strong>。</li><li>收到 <code>HTTP/1.x</code>（x ≥ 2，如 <code>HTTP/1.9</code>）→ 当作 HTTP/1.1 处理（同 major 版本向前兼容）。</li><li>响应中回送的版本是<strong>服务端自身支持的最高版本</strong>（在同一 major 内），不是照抄请求版本。</li><li><code>HTTP/1.1</code> 请求 <strong>MUST</strong> 带 <code>Host</code>；缺失或多于一个 → <strong>400</strong>。</li></ul><h2 id="与-host-的关系" tabindex="-1">与 Host 的关系 <a class="header-anchor" href="#与-host-的关系" aria-label="Permalink to &quot;与 Host 的关系&quot;">​</a></h2><p><code>Host</code> 携带目标 authority，是 HTTP/1.1 虚拟主机的基础：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host = uri-host [ &quot;:&quot; port ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>优先级：<strong>absolute-form 的 authority &gt; Host 字段</strong>。服务端据此决定虚拟主机时必须遵循该优先级，否则出现 Host 混淆攻击。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/status-line">状态行</a>——版本、三位状态码与 reason-phrase。</p>`,40)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
